mapper.select:
select cm.id, user.id as userId, user.name as username, color, content, label.name as label, like_count, comment_count, cm.create_time as date from card_message as cm left join label on cm.label_id = label.id left join user on cm.user_id = user.id
label.id = #{labelId}
and cm.deleted = 0
order by cm.user_id = #{userId} desc, cm.id limit #{page}, #{pageSize}
